/* Carbine tooling: generators for Ninja, Make, CMake and Meson.
 *
 * Ninja and Make are emitted from the same step plan the native executor
 * runs, one edge or rule per step. CMake and Meson are emitted from the
 * target declarations, using their native library and executable rules;
 * programs (.c15) become custom commands in both.
 *
 * Generated files are written to the project root and use paths relative
 * to it, so the generator must be run from that root. */
#include "internal.h"

#include <errno.h>
#include <stdio.h>
#include <string.h>

#define TRY(expr) do { cb_status _st = (expr); if (_st != CB_OK) return _st; } while (0)

const char *cb_backend_file(cb_backend b) {
    switch (b) {
    case CB_BACKEND_NINJA: return "build.ninja";
    case CB_BACKEND_MAKE: return "Makefile";
    case CB_BACKEND_CMAKE: return "CMakeLists.txt";
    case CB_BACKEND_MESON: return "meson.build";
    }
    return NULL;
}

/* Every generated language here uses '#' for comments. */
static cb_status banner(cb_buf *out, const char *file, const char *project) {
    return cb_buf_printf(out,
        "# Generated by Carbine %s from %s for %s. Do not edit.\n\n",
        cb_version(), project, file);
}

/* Directory part of a root-relative path ("build/obj/x/a.o" -> "build/obj/x"). */
static void dirname_of(const char *path, char *dir, size_t cap) {
    const char *slash = strrchr(path, '/');
    size_t n = slash ? (size_t)(slash - path) : 0;
    if (n >= cap) n = cap - 1;
    memcpy(dir, path, n);
    dir[n] = '\0';
}

/* The shell command of a step, with a mkdir for its output directory. */
static cb_status step_shell(const cb_step *s, cb_buf *cmd) {
    char dir[512];
    size_t i;
    cb_buf_init(cmd);
    dirname_of(s->output, dir, sizeof dir);
    if (dir[0]) {
        TRY(cb_buf_puts(cmd, "mkdir -p "));
        TRY(cb_fmt_shell(cmd, dir));
        TRY(cb_buf_puts(cmd, " && "));
    }
    for (i = 0; i < s->argv.count; ++i) {
        if (i) TRY(cb_buf_add(cmd, " ", 1));
        TRY(cb_fmt_shell(cmd, s->argv.items[i]));
    }
    return CB_OK;
}

/* Final outputs (archives, executables, programs) for default goals. */
static int is_final(const cb_step *s) { return s->kind != CB_STEP_COMPILE; }

/* ---------- Ninja ---------- */

static cb_status emit_ninja(const cb_model *m, cb_buf *out) {
    size_t t, i;
    cb_plan plan;

    TRY(banner(out, "build.ninja", m->project));
    TRY(cb_buf_puts(out, "ninja_required_version = 1.7\n\n"));
    TRY(cb_buf_puts(out, "rule run\n  command = $cmd\n  description = BUILD $out\n\n"));

    for (t = 0; t < m->count; ++t) {
        cb_status st;
        if ((st = cb_plan_target(m, t, &plan)) != CB_OK) return st;
        for (i = 0; i < plan.count; ++i) {
            const cb_step *s = &plan.steps[i];
            cb_buf cmd, edge;
            size_t k;
            cb_buf_init(&edge);
            TRY(cb_fmt_ninja_path(&edge, s->output));
            TRY(cb_buf_puts(out, "build "));
            TRY(cb_buf_add(out, edge.data, edge.len));
            cb_buf_free(&edge);
            TRY(cb_buf_puts(out, ": run"));
            for (k = 0; k < s->inputs.count; ++k) {
                cb_buf p;
                cb_buf_init(&p);
                TRY(cb_buf_puts(out, " "));
                TRY(cb_fmt_ninja_path(&p, s->inputs.items[k]));
                TRY(cb_buf_add(out, p.data, p.len));
                cb_buf_free(&p);
            }
            TRY(cb_buf_puts(out, "\n  cmd = "));
            TRY(step_shell(s, &cmd));
            {
                cb_buf esc;
                cb_buf_init(&esc);
                TRY(cb_fmt_ninja(&esc, cmd.data));
                TRY(cb_buf_add(out, esc.data, esc.len));
                cb_buf_free(&esc);
            }
            cb_buf_free(&cmd);
            TRY(cb_buf_puts(out, "\n"));
        }
        cb_plan_free(&plan);
    }
    TRY(cb_buf_puts(out, "\n# Default goal: every archive, executable and program.\n"));
    TRY(cb_buf_puts(out, "build all: phony"));
    for (t = 0; t < m->count; ++t) {
        cb_status st;
        size_t i2;
        if ((st = cb_plan_target(m, t, &plan)) != CB_OK) return st;
        for (i2 = 0; i2 < plan.count; ++i2) {
            cb_buf p;
            if (!is_final(&plan.steps[i2])) continue;
            cb_buf_init(&p);
            TRY(cb_buf_puts(out, " "));
            TRY(cb_fmt_ninja_path(&p, plan.steps[i2].output));
            TRY(cb_buf_add(out, p.data, p.len));
            cb_buf_free(&p);
        }
        cb_plan_free(&plan);
    }
    TRY(cb_buf_puts(out, "\ndefault all\n"));
    return CB_OK;
}

/* ---------- Make ---------- */

static cb_status emit_make(const cb_model *m, cb_buf *out) {
    size_t t, i;
    cb_plan plan;
    cb_buf goals;

    cb_buf_init(&goals);
    TRY(banner(out, "Makefile", m->project));
    for (t = 0; t < m->count; ++t) {
        cb_status st;
        if ((st = cb_plan_target(m, t, &plan)) != CB_OK) { cb_buf_free(&goals); return st; }
        for (i = 0; i < plan.count; ++i) {
            if (!is_final(&plan.steps[i])) continue;
            TRY(cb_buf_puts(&goals, " "));
            TRY(cb_fmt_make_path(&goals, plan.steps[i].output));
        }
        cb_plan_free(&plan);
    }
    TRY(cb_buf_puts(out, "all:"));
    TRY(cb_buf_add(out, goals.data ? goals.data : "", goals.len));
    TRY(cb_buf_puts(out, "\n\n"));
    cb_buf_free(&goals);

    for (t = 0; t < m->count; ++t) {
        cb_status st;
        if ((st = cb_plan_target(m, t, &plan)) != CB_OK) return st;
        for (i = 0; i < plan.count; ++i) {
            const cb_step *s = &plan.steps[i];
            cb_buf cmd, target;
            size_t k;

            cb_buf_init(&target);
            TRY(cb_fmt_make_path(&target, s->output));
            TRY(cb_buf_add(out, target.data, target.len));
            cb_buf_free(&target);
            TRY(cb_buf_puts(out, ":"));
            for (k = 0; k < s->inputs.count; ++k) {
                cb_buf p;
                cb_buf_init(&p);
                TRY(cb_buf_puts(out, " "));
                TRY(cb_fmt_make_path(&p, s->inputs.items[k]));
                TRY(cb_buf_add(out, p.data, p.len));
                cb_buf_free(&p);
            }
            TRY(cb_buf_puts(out, "\n\t@"));
            TRY(step_shell(s, &cmd));
            {
                cb_buf esc;
                cb_buf_init(&esc);
                TRY(cb_fmt_make(&esc, cmd.data));
                TRY(cb_buf_add(out, esc.data, esc.len));
                cb_buf_free(&esc);
            }
            cb_buf_free(&cmd);
            TRY(cb_buf_puts(out, "\n\n"));
        }
        cb_plan_free(&plan);
    }
    TRY(cb_buf_puts(out, "clean:\n\trm -rf build\n\n.PHONY: all clean\n"));
    return CB_OK;
}

/* ---------- CMake ---------- */

static cb_status cmake_list(cb_buf *out, const cb_list *items, const char *leader) {
    size_t i;
    for (i = 0; i < items->count; ++i) {
        TRY(cb_buf_puts(out, leader));
        TRY(cb_fmt_cmake(out, items->items[i]));
    }
    return CB_OK;
}

/* Target-level arguments common to library and executable targets. */
static cb_status cmake_target_args(const cb_model *m, const cb_target *t, const char *name, cb_buf *out) {
    size_t k;
    (void)m;
    if (t->includes.count) {
        TRY(cb_buf_printf(out, "target_include_directories(%s PRIVATE", name));
        TRY(cmake_list(out, &t->includes, " "));
        TRY(cb_buf_puts(out, ")\n"));
    }
    if (t->defines.count) {
        TRY(cb_buf_printf(out, "target_compile_definitions(%s PRIVATE", name));
        TRY(cmake_list(out, &t->defines, " "));
        TRY(cb_buf_puts(out, ")\n"));
    }
    if (t->flags.count) {
        TRY(cb_buf_printf(out, "target_compile_options(%s PRIVATE", name));
        TRY(cmake_list(out, &t->flags, " "));
        TRY(cb_buf_puts(out, ")\n"));
    }
    (void)k;
    return CB_OK;
}

static cb_status emit_cmake(const cb_model *m, cb_buf *out) {
    size_t t;
    cb_buf project;

    cb_buf_init(&project);
    TRY(cb_fmt_cmake(&project, m->project));
    TRY(banner(out, "CMakeLists.txt", m->project));
    TRY(cb_buf_puts(out, "cmake_minimum_required(VERSION 3.16)\n"));
    TRY(cb_buf_printf(out, "project(%s C)\n\n", project.data));
    cb_buf_free(&project);
    TRY(cb_buf_puts(out,
        "if(NOT DEFINED QSCRIPT_EXECUTABLE)\n"
        "  set(QSCRIPT_EXECUTABLE qscript)\n"
        "endif()\n\n"));

    for (t = 0; t < m->count; ++t) {
        const cb_target *tg = &m->targets[t];
        cb_buf name;
        cb_buf_init(&name);
        TRY(cb_fmt_cmake(&name, tg->name));
        if (tg->kind == CB_KIND_LIB) {
            TRY(cb_buf_printf(out, "add_library(%s STATIC", name.data));
            TRY(cmake_list(out, &tg->files, " "));
            TRY(cb_buf_puts(out, ")\n"));
            TRY(cmake_target_args(m, tg, name.data, out));
        } else if (tg->kind == CB_KIND_EXE) {
            size_t k;
            TRY(cb_buf_printf(out, "add_executable(%s", name.data));
            TRY(cmake_list(out, &tg->files, " "));
            TRY(cb_buf_puts(out, ")\n"));
            TRY(cmake_target_args(m, tg, name.data, out));
            if (tg->dep_count) {
                TRY(cb_buf_printf(out, "target_link_libraries(%s PRIVATE", name.data));
                for (k = 0; k < tg->dep_count; ++k) {
                    if (m->targets[tg->dep_ids[k]].kind != CB_KIND_LIB) continue;
                    TRY(cb_buf_puts(out, " "));
                    TRY(cb_fmt_cmake(out, m->targets[tg->dep_ids[k]].name));
                }
                TRY(cb_buf_puts(out, ")\n"));
            }
        } else {
            /* Program: a custom command that runs qscript build. */
            cb_buf outp;
            cb_buf_init(&outp);
            TRY(cb_buf_printf(&outp, "${CMAKE_CURRENT_SOURCE_DIR}/build/%s", tg->name));
            TRY(cb_buf_printf(out, "add_custom_command(OUTPUT %s\n", outp.data));
            TRY(cb_buf_puts(out, "  COMMAND ${CMAKE_COMMAND} -E make_directory ${CMAKE_CURRENT_SOURCE_DIR}/build\n"));
            TRY(cb_buf_puts(out, "  COMMAND ${QSCRIPT_EXECUTABLE}"));
            TRY(cmake_list(out, &tg->flags, " "));
            TRY(cb_buf_puts(out, " build"));
            TRY(cmake_list(out, &tg->files, " "));
            TRY(cb_buf_printf(out, " -o %s\n", outp.data));
            TRY(cb_buf_puts(out, "  DEPENDS"));
            TRY(cmake_list(out, &tg->files, " "));
            TRY(cb_buf_puts(out, "\n  WORKING_DIRECTORY ${CMAKE_CURRENT_SOURCE_DIR})\n"));
            TRY(cb_buf_printf(out, "add_custom_target(%s ALL DEPENDS %s)\n", name.data, outp.data));
            cb_buf_free(&outp);
        }
        TRY(cb_buf_puts(out, "\n"));
        cb_buf_free(&name);
    }
    return CB_OK;
}

/* ---------- Meson ---------- */

static cb_status meson_list(cb_buf *out, const cb_list *items) {
    size_t i;
    TRY(cb_buf_puts(out, "["));
    for (i = 0; i < items->count; ++i) {
        if (i) TRY(cb_buf_puts(out, ", "));
        TRY(cb_fmt_meson(out, items->items[i]));
    }
    return cb_buf_puts(out, "]");
}

/* Identifier for a target: letters, digits and underscores only. */
static void ident_of(const char *name, char *out, size_t cap) {
    size_t i, n = 0;
    for (i = 0; name[i] && n + 1 < cap; ++i)
        out[n++] = (name[i] >= 'a' && name[i] <= 'z') || (name[i] >= 'A' && name[i] <= 'Z') ||
                   (name[i] >= '0' && name[i] <= '9') ? name[i] : '_';
    out[n] = '\0';
}

static cb_status emit_meson(const cb_model *m, cb_buf *out) {
    size_t t, k;
    TRY(banner(out, "meson.build", m->project));
    TRY(cb_buf_puts(out, "project("));
    TRY(cb_fmt_meson(out, m->project));
    TRY(cb_buf_puts(out, ", 'c', version: '" "1.0.0" "', default_options: ['c_std=c11', 'warning_level=2'])\n\n"));
    TRY(cb_buf_puts(out, "qscript = find_program('qscript')\n\n"));

    for (t = 0; t < m->count; ++t) {
        const cb_target *tg = &m->targets[t];
        char id[256];
        ident_of(tg->name, id, sizeof id);
        if (tg->includes.count) {
            TRY(cb_buf_printf(out, "inc_%s = include_directories(", id));
            TRY(meson_list(out, &tg->includes));
            TRY(cb_buf_puts(out, ")\n"));
        }
        if (tg->kind == CB_KIND_PROGRAM) {
            TRY(cb_buf_printf(out, "%s = custom_target(", id));
            TRY(cb_fmt_meson(out, tg->name));
            TRY(cb_buf_puts(out, ",\n  input: "));
            TRY(meson_list(out, &tg->files));
            TRY(cb_buf_printf(out, ",\n  output: "));
            TRY(cb_fmt_meson(out, tg->name));
            TRY(cb_buf_puts(out, ",\n  command: [qscript"));
            for (k = 0; k < tg->flags.count; ++k) {
                TRY(cb_buf_puts(out, ", "));
                TRY(cb_fmt_meson(out, tg->flags.items[k]));
            }
            TRY(cb_buf_puts(out, ", 'build', '@INPUT@', '-o', '@OUTPUT@'],\n  build_by_default: true)\n\n"));
            continue;
        }
        TRY(cb_buf_printf(out, "%s = %s(", id, tg->kind == CB_KIND_LIB ? "static_library" : "executable"));
        TRY(cb_fmt_meson(out, tg->name));
        TRY(cb_buf_puts(out, ", "));
        TRY(meson_list(out, &tg->files));
        if (tg->includes.count) TRY(cb_buf_printf(out, ", include_directories: inc_%s", id));
        if (tg->defines.count || tg->flags.count) {
            cb_list args = {0};
            size_t j;
            cb_list_init(&args);
            for (j = 0; j < tg->defines.count; ++j) {
                cb_buf d; cb_buf_init(&d);
                cb_buf_printf(&d, "-D%s", tg->defines.items[j]);
                cb_list_push(&args, d.data);
                cb_buf_free(&d);
            }
            cb_list_append(&args, &tg->flags);
            TRY(cb_buf_puts(out, ", c_args: "));
            TRY(meson_list(out, &args));
            cb_list_free(&args);
        }
        if (tg->kind == CB_KIND_EXE) {
            size_t n = 0;
            for (k = 0; k < tg->dep_count; ++k) {
                const cb_target *d = &m->targets[tg->dep_ids[k]];
                char did[256];
                if (d->kind != CB_KIND_LIB) continue;
                ident_of(d->name, did, sizeof did);
                TRY(cb_buf_printf(out, "%s%s", n++ ? ", " : ", link_with: [", did));
            }
            if (n) TRY(cb_buf_puts(out, "]"));
        }
        TRY(cb_buf_puts(out, ")\n\n"));
    }
    return CB_OK;
}

/* ---------- entry points ---------- */

cb_status cb_emit(const cb_model *m, cb_backend backend, cb_buf *out) {
    cb_buf_init(out);
    if (!m->resolved) {
        cb_set_error("model is not resolved");
        return CB_INVALID_ARGUMENT;
    }
    switch (backend) {
    case CB_BACKEND_NINJA: return emit_ninja(m, out);
    case CB_BACKEND_MAKE: return emit_make(m, out);
    case CB_BACKEND_CMAKE: return emit_cmake(m, out);
    case CB_BACKEND_MESON: return emit_meson(m, out);
    }
    cb_set_error("unknown backend");
    return CB_INVALID_ARGUMENT;
}

cb_status cb_emit_file(const cb_model *m, cb_backend backend) {
    cb_buf text;
    char path[1200];
    FILE *f;
    cb_status st = cb_emit(m, backend, &text);
    if (st != CB_OK) return st;
    snprintf(path, sizeof path, "%s/%s", m->root, cb_backend_file(backend));
    f = fopen(path, "wb");
    if (!f) {
        cb_set_error("cannot write %s: %s", path, strerror(errno));
        cb_buf_free(&text);
        return CB_IO_ERROR;
    }
    if (fwrite(text.data, 1, text.len, f) != text.len) st = CB_IO_ERROR;
    if (fclose(f) != 0) st = CB_IO_ERROR;
    cb_buf_free(&text);
    return st;
}
